<?php if(can($pdo,$user,'leave.create')):?><details class="card core-editor" <?=$error?'open':''?>><summary>Create leave request</summary><form method="post" enctype="multipart/form-data" class="form-grid core-form"><?php ftoken();chr_hidden('action','core_leave');$v=$error?$_POST:[];chr_select('employee_id','Employee',$v['employee_id']??'', [''=>'Select employee']+$employeeOptions);$activeTypes=[];foreach(chr_rows($pdo,'leave_policy') as $p)if($p['status']==='Published')$activeTypes[$p['values']['type']]=$p['title'];chr_select('category','Leave type',$v['category']??'', [''=>'Select type']+$activeTypes);field('start_date','From',$v,'date',true);field('end_date','To',$v,'date',true);choose('day_part','Day period',$v,['Full Day','First Half','Second Half']);field('subject','Subject',$v,'text',true,180);?><label class="full">Reason<textarea name="details" maxlength="5000" required><?=h($v['details']??'')?></textarea></label><label>Optional attachment<input type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png"></label><p class="full">Published holidays and assigned weekly offs are excluded. Half-day requests cover one date and count as 0.5 day. Without an assigned shift, no weekly off is assumed. Requests become effective only after approval.</p><div class="full"><button class="button primary">Submit request</button></div></form></details><?php endif;?>
<form method="get" class="card form-grid core-form"><?php chr_hidden('page',$page);chr_select('employee_id','Employee',$_GET['employee_id']??'', [''=>'All employees']+$historyEmployeeOptions);chr_select('department_id','Department',$_GET['department_id']??'', [''=>'All departments']+$departmentOptions);chr_select('category','Leave type',$_GET['category']??'', [''=>'All types']+$leaveOptions);chr_select('status','Status',$_GET['status']??'', [''=>'All statuses','Pending'=>'Pending','Approved'=>'Approved','Rejected'=>'Rejected','Cancelled'=>'Cancelled']);field('from','From (optional)',$_GET,'date');field('to','To (optional)',$_GET,'date');?><div class="full"><button class="button primary">Apply filters</button></div></form>
<?php
$where=["r.kind='leave'"];$args=[];foreach(['employee_id'=>'r.user_id','department_id'=>'e.department_id','category'=>'r.category','status'=>'r.status'] as $key=>$column)if(!empty($_GET[$key])){$where[]=$column.'=?';$args[]=$_GET[$key];}try{if(!empty($_GET['from'])){$where[]='r.end_date>=?';$args[]=chr_date($_GET['from']);}if(!empty($_GET['to'])){$where[]='r.start_date<=?';$args[]=chr_date($_GET['to']);}}catch(InvalidArgumentException $e){echo '<div class="alert error">'.h($e->getMessage()).'</div>';return;}
$base=' FROM hr_requests r JOIN users u ON u.id=r.user_id LEFT JOIN employees e ON e.user_id=r.user_id LEFT JOIN users reviewer ON reviewer.id=r.reviewer_id LEFT JOIN hr_leave_details ld ON ld.request_id=r.id WHERE '.implode(' AND ',$where);$q=$pdo->prepare('SELECT COUNT(*)'.$base);$q->execute($args);$count=(int)$q->fetchColumn();$number=max(1,(int)($_GET['p']??1));$offset=($number-1)*30;$q=$pdo->prepare('SELECT r.*,u.name,reviewer.name reviewer_name,ld.days,ld.day_part,ld.attachment_record_id'.$base.' ORDER BY r.id DESC LIMIT 30 OFFSET '.$offset);$q->execute($args);$requests=$q->fetchAll(PDO::FETCH_ASSOC);
?><section class="card"><div class="table-scroll"><table class="directory"><thead><tr><th>Employee</th><th>Type / period</th><th>Dates</th><th>Days</th><th>Reason</th><th>Applied</th><th>Status / reviewer</th><th>Actions</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="8">No matching requests.</td></tr><?php endif;foreach($requests as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['category'])?><small><?=h($r['day_part']??'Full Day (legacy)')?></small></td><td><?=h($r['start_date'])?> → <?=h($r['end_date'])?></td><td><?=h($r['days']??count(chr_request_days($pdo,$r)))?></td><td><details><summary><?=h($r['subject'])?></summary><p><?=nl2br(h($r['details']))?></p><?php if($r['attachment_record_id']):$f=$pdo->prepare('SELECT id FROM hr_files WHERE record_id=? ORDER BY id DESC LIMIT 1');$f->execute([$r['attachment_record_id']]);$fid=$f->fetchColumn();if($fid):?><a href="document.php?id=<?=(int)$fid?>">Download attachment</a><?php endif;endif;?></details></td><td><?=h($r['created_at'])?></td><td><?php fbadge($r['status'],$r['status']==='Approved');?><small><?=h($r['reviewer_name']??'Awaiting review')?></small></td><td><?php if(($r['status']==='Pending'&&can($pdo,$user,'leave.approve'))||(in_array($r['status'],['Pending','Approved'],true)&&can($pdo,$user,'leave.manage'))):?><form method="post" data-confirm="Save this leave decision?"><?php ftoken();chr_hidden('action','core_review');chr_hidden('id',$r['id']);if($r['status']==='Pending'&&can($pdo,$user,'leave.approve')):?><button class="button primary" name="status" value="Approved">Approve</button><button class="button" name="status" value="Rejected">Reject</button><?php endif;if(can($pdo,$user,'leave.manage')):?><button class="button" name="status" value="Cancelled">Cancel</button><?php endif;?></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Leave pages"><?php for($i=max(1,$number-2);$i<=min((int)ceil($count/30),$number+2);$i++):?><a class="button" href="?<?=h(http_build_query(array_merge($_GET,['p'=>$i])))?>"><?=$i?></a><?php endfor;?></nav></section><p>Legacy requests retain their original calendar-day accounting. New requests use the stored day breakdown. Cancelling an approved request releases its balance without deleting its history.</p>
